import {bindDrawing} from './drawing.js';
import {STICKERS,sticker} from './icons.js';
import {recordCompositionVideo,videoSupported} from './video.js';
import {TOYS,SHAPES,toyArt,SCENE,ICONS,defaultStrokes,graphSVG,soundStrokes} from './art.js';
import {getAudio,decodeBlob,playToy,playTone,playRecording,playComposition,renderComposition,stopAudio,sceneDuration} from './audio.js';
import {INSTRUMENTS,NOTES,OCTAVES,normalizeTone,isPitched,toneLabel} from './music.js';
import {KEY,freshProject,validateProject,loadProject,loadClips,putClip,replaceClips,clipToDataURL,dataURLToClip} from './storage.js';

const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={project:loadProject(),view:0,toy:'slide',palette:'slide',slot:0,visited:new Set(['slide']),playing:false,presenting:false,busy:false,pendingMic:false,paletteArmed:false,recorder:null,recStarted:0,recordingToy:null,toneEditor:null,movementEditor:null};
let videoAbort=null,videoURL=null,movementDrawing=null;
let clips=new Map(),buffers=new Map(),saveTimer,toastTimer,recordTimer,recordTick,raf,previewTimer,storageOK=true;
const root=$('#app');
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function save(){clearTimeout(saveTimer);saveTimer=setTimeout(()=>{try{localStorage.setItem(KEY,JSON.stringify(state.project));storageOK=true;}catch{storageOK=false;toast('이 브라우저에 저장하지 못했어요. 사용 안내에서 작품 파일을 저장해 주세요.');}const s=$('.save-status');if(s)s.textContent=storageOK?'이 기기에 자동 저장':'작품 파일로 저장해요';},200);}
function nameOf(id){return TOYS.find(t=>t.id===id).name;}
function soundOf(id){return state.project.sounds[id];}
function toneButton(raw,target){const t=normalizeTone(raw),i=INSTRUMENTS.find(i=>i.id===t.instrument);return `<button class="tone-open" data-action="open-tone" data-target="${target}" aria-label="${target==='slot'?'이 장면':'놀이기구'} 악기와 음정 바꾸기"><b>${sticker('xylophone')}악기·음정</b><small>${i.name}${i.pitched?' · '+NOTES.find(n=>n.id===t.note).name:''}</small></button>`;}
function musicSummary(slot){return toneLabel(slot.tone)+(isPitched(slot.tone)?' · '+(slot.tone.pitchMode==='fixed'?'한 음':'그림선'):'');}
function openTone(target){stopPlayback();const source=target==='slot'?state.project.slots[state.slot]:soundOf(state.toy);if(!source)return;state.toneEditor={target,id:target==='slot'?state.slot:state.toy,tone:normalizeTone(source.tone)};$('#tone-title').textContent=(target==='slot'?`${state.slot+1}번 장면`:nameOf(state.toy))+'의 악기와 음정';renderToneEditor();$('#tone-dialog').showModal();}
function renderToneEditor(focusSelector){const editor=state.toneEditor;if(!editor)return;const t=editor.tone,pitched=isPitched(t);$('#tone-editor').innerHTML=`<span class="field-label">어떤 악기로 표현할까요?</span><div class="instrument-grid" role="group" aria-label="악기 종류">${INSTRUMENTS.map(i=>`<button class="instrument-choice ${t.instrument===i.id?'chosen':''}" data-action="tone-instrument" data-value="${i.id}" aria-pressed="${t.instrument===i.id}"><span class="instrument-symbol" aria-hidden="true">${STICKERS[i.id]}</span><span><b>${i.name}</b><small>${i.hint}</small></span></button>`).join('')}</div><div class="pitch-controls ${pitched?'':'unpitched'}"><div class="tone-label-row"><span class="field-label">음정 고르기</span><span>눌러서 소리를 들어요</span></div><div class="note-keyboard" role="group" aria-label="음정">${NOTES.map(n=>`<button class="note-key ${t.note===n.id?'chosen':''}" data-action="tone-note" data-value="${n.id}" aria-pressed="${t.note===n.id}" ${pitched?'':'disabled'}><b>${n.name}</b><small>${n.id}</small></button>`).join('')}</div><div class="tone-label-row"><span class="field-label">음높이</span></div><div class="tone-segments" role="group" aria-label="음높이">${OCTAVES.map(o=>`<button class="${t.octave===o.id?'chosen':''}" data-action="tone-setting" data-key="octave" data-value="${o.id}" aria-pressed="${t.octave===o.id}" ${pitched?'':'disabled'}>${o.name}</button>`).join('')}</div><div class="tone-label-row"><span class="field-label">어떻게 연주할까요?</span></div><div class="tone-segments" role="group" aria-label="음정 표현 방법">${[['follow','그림선 따라'],['fixed','한 음으로']].map(([v,l])=>`<button class="${t.pitchMode===v?'chosen':''}" data-action="tone-setting" data-key="pitchMode" data-value="${v}" aria-pressed="${t.pitchMode===v}" ${pitched?'':'disabled'}>${l}</button>`).join('')}</div></div><p class="tone-help" role="status">${!pitched?'마라카스와 북은 음정 대신 리듬으로 표현해요. 빠르기와 소리 크기를 바꿔 보세요.':t.pitchMode==='fixed'?`고른 ‘${NOTES.find(n=>n.id===t.note).name}’ 음으로 연주해요. 그림선은 소리가 시작하는 때와 길이를 나타내요.`:`고른 ‘${NOTES.find(n=>n.id===t.note).name}’를 가운데 기준음으로 삼아, 그림선의 높낮이에 따라 음이 바뀌어요.`}</p><p class="tone-scope">${editor.target==='slot'?'이 장면만 바뀌어요. 선택한 악기로 음악을 연주해요.':'새로 악보에 담는 장면의 기본 소리예요. 악보에서 장면마다 다시 바꿀 수 있어요.'}</p>`;if(focusSelector)$('#tone-editor').querySelector(focusSelector)?.focus();}
function closeTone(){stopPlayback();$('#tone-dialog').close();state.toneEditor=null;}
function applyTone(){const editor=state.toneEditor;if(!editor)return;const source=editor.target==='slot'?state.project.slots[editor.id]:soundOf(editor.id);if(source){source.tone=normalizeTone(editor.tone);if(editor.target==='slot')source.mode='music';}closeTone();save();render();}
async function previewTone(){const e=state.toneEditor;if(!e)return;stopPlayback();const slot=e.target==='slot'?state.project.slots[e.id]:null,id=slot?.toyId||e.id,settings={...soundOf(id),tone:e.tone};await playToy(id,settings,slot?.strokes??soundStrokes(soundOf(id)));}
function header(){return `<header class="topbar"><button class="brand" data-action="view" data-view="0" aria-label="소리랑 놀이터 첫 화면"><span class="brand-symbol">${sticker('xylophone')}</span><span><b>소리랑 놀이터</b><small>소리로 노는 나만의 음악 시간</small></span></button><nav class="steps" aria-label="활동 순서">${['소리 찾기','악보 만들기','내 작품 발표'].map((s,i)=>`<button class="step ${state.view===i?'active':''}" data-action="view" data-view="${i}" ${state.view===i?'aria-current="step"':''}><span class="num">${i+1}</span>${sticker(['mic','pencil','music'][i],'step-sticker')}${s}</button>`).join('')}</nav><div class="top-tools"><span class="save-status">${storageOK?'이 기기에 자동 저장':'작품 파일로 저장해요'}</span><button class="icon-btn" data-action="help" aria-label="사용 안내">${sticker('help')}</button></div></header>`;}
function intro(eyebrow,title,description){return `<div class="intro"><div><span class="eyebrow">${eyebrow}</span><h1>${sticker(['music','pencil','bell'][state.view])}${title}</h1><p>${description}</p></div><div class="personal-identity"><label for="student-name">내 이름</label><input id="student-name" class="name-input" data-field="studentName" value="${esc(state.project.studentName)}" maxlength="24" placeholder="이름을 적어요" autocomplete="off"><span>나만의 음악을 만들어요</span></div></div>`;}
function footer(left,button,action){return `<div class="footer-bar"><div class="footer-tip">${left}</div><button class="btn primary next-btn" data-action="${action}">${button} ${ICONS.arrow}</button></div><div class="footer-credit">작은 움직임에서 시작하는 나만의 음악</div>`;}
function settingsPanel(){const t=TOYS.find(t=>t.id===state.toy),s=soundOf(t.id),has=clips.has(t.id),recording=!!state.recorder;return `<section class="panel" aria-label="${esc(nameOf(t.id))} 소리 표현"><div class="panel-head"><div><span class="small-label">나만의 소리를 발견해요</span><h2>${esc(nameOf(t.id))}</h2></div>${toneButton(s.tone,'toy')}</div><p class="panel-question">${t.question}</p><label class="field-label first" for="sound-word">어떤 소리말로 표현할까요?</label><div class="word-row"><input id="sound-word" class="word-input" data-field="soundWord" maxlength="48" value="${esc(s.word)}" placeholder="나만의 소리말을 써요"></div><div class="field-block movement-field"><div class="movement-heading"><span class="field-label">소리의 움직임</span><button class="movement-draw-btn" data-action="open-movement" data-target="toy">${sticker('pencil')} 직접 그리기</button></div>${Array.isArray(s.strokes)?`<button class="movement-preview" data-action="open-movement" data-target="toy" aria-label="내가 그린 소리의 움직임 다시 그리기"><span>${s.strokes.length?'내가 그린 움직임':'소리 없이 쉬어요'}</span>${graphSVG(s.strokes,t.color)}<small>눌러서 다시 그려요</small></button>`:`<div class="shape-options" role="group" aria-label="소리의 움직임">${SHAPES.map(x=>`<button class="shape-btn ${s.shape===x.id?'chosen':''}" data-action="shape" data-value="${x.id}" aria-pressed="${s.shape===x.id}"><span class="shape-glyph">${x.glyph}</span><small>${x.label}</small></button>`).join('')}</div>`}</div><div class="control-line"><span class="field-label">빠르기</span><div class="segments" role="group" aria-label="소리 빠르기">${[['slow','느리게'],['normal','보통'],['fast','빠르게']].map(([v,l])=>`<button class="${s.speed===v?'chosen':''}" data-action="setting" data-key="speed" data-value="${v}" aria-pressed="${s.speed===v}">${l}</button>`).join('')}</div></div><div class="control-line"><span class="field-label">소리 크기</span><div class="segments" role="group" aria-label="소리 크기">${[['soft','작게'],['normal','보통'],['loud','크게']].map(([v,l])=>`<button class="${s.volume===v?'chosen':''}" data-action="setting" data-key="volume" data-value="${v}" aria-pressed="${s.volume===v}">${l}</button>`).join('')}</div></div><div class="panel-actions"><button class="btn orange" data-action="preview" ${recording?'disabled':''}>${ICONS.music} 음악으로 듣기</button><button class="btn secondary rec-btn ${recording?'recording':''}" data-action="record">${recording?ICONS.stop:ICONS.mic}<span id="rec-label">${recording?'녹음 끝내기':has?'목소리 다시 녹음':'내 목소리 녹음'}</span></button></div><div class="rec-meta">${recording?'<span>6초가 되면 자동으로 끝나요</span>':has?`<span class="recording-controls"><button data-action="listen-voice">▶ 내 목소리 듣기</button><button data-action="download-voice">저장</button></span><button data-action="remove-voice">녹음 지우기</button>`:'<span>목소리로 흉내 내고, 원하면 녹음해요.</span><span>최대 6초</span>'}</div></section>`;}
function sceneView(big=false){return `<div class="playground illustrated ${big?'large-scene':''}"><img class="scene-picture" src="${SCENE.src}" width="${SCENE.width}" height="${SCENE.height}" alt="음악책에 나온 미끄럼틀, 소리 전달 놀이기구, 회전 놀이기구, 시소, 오르기 놀이기구에서 아이들이 노는 모습" fetchpriority="high">${TOYS.map((t,i)=>`<button class="scene-hotspot ${state.toy===t.id?'selected':''}" style="left:${t.zone[0]}%;top:${t.zone[1]}%;width:${t.zone[2]}%;height:${t.zone[3]}%" data-action="toy" data-toy="${t.id}" aria-pressed="${state.toy===t.id}" aria-label="${esc(nameOf(t.id))} 소리 표현하기"><span class="toy-name"><span class="toy-badge">${i+1}</span>${esc(nameOf(t.id))}</span></button>`).join('')}</div>`;}
function explore(){return intro('소리 하나 · 귀 쫑긋, 소리 탐험','놀이터에 귀를 기울여요','그림 속 놀이기구를 눌러요. 움직이는 모습을 내 목소리로 표현해 볼까요?')+`<div class="explore-layout"><section class="playground-wrap" aria-label="소리 놀이터">${sceneView()}<div class="scene-bottom"><span>✦ 나만의 소리를 마음껏 표현해요.</span><button class="btn secondary scene-expand" data-action="show-scene">${ICONS.expand} 그림 크게 보기</button></div><div class="explored-count"><span class="dots">${TOYS.map(t=>`<i class="${state.visited.has(t.id)?'on':''}"></i>`).join('')}</span><span>${state.visited.size} / ${TOYS.length} 둘러보기</span></div></section>${settingsPanel()}</div>`+footer('<b>나만의 표현을 찾아봐요.</b><br>같은 놀이기구라도 다른 소리로 표현할 수 있어요.','내 그림 악보 만들기','next');}
function slotHTML(slot,i,concert=false){const t=slot?TOYS.find(t=>t.id===slot.toyId):null;return `<div class="score-slot ${!concert&&i===state.slot?'selected':''}" data-slot-index="${i}"><button class="slot-pick" data-action="${concert?'play-slot':'select-slot'}" data-index="${i}" aria-label="${i+1}번 장면 ${t?esc(nameOf(t.id)):'빈칸'} ${concert?'듣기':'선택'}"><span class="slot-num">${i+1}번째 장면</span></button>${!concert&&slot?`<button class="slot-remove" data-action="remove-slot" data-index="${i}" aria-label="${i+1}번 장면 지우기">×</button>`:''}${t?`<button class="slot-content" data-action="${concert?'play-slot':'select-slot'}" data-index="${i}">${toyArt(t.id,'slot-art')}<span class="slot-title">${esc(nameOf(t.id))}</span><span class="slot-word" style="color:${t.color}">${esc(slot.word||soundOf(t.id).word)}</span><div class="slot-graph">${graphSVG(slot.strokes,t.color)}</div></button><div class="slot-mode">${slot.mode==='voice'?(clips.has(t.id)?'● 내가 녹음한 목소리':'♫ 음악 · 녹음 없음'):'♫ '+esc(musicSummary(slot))}</div>`:`<button class="slot-empty" data-action="${concert?'empty-slot':'select-slot'}" data-index="${i}"><b>+</b><span>${concert?'쉬어 가는 장면':'소리를 담아요'}</span></button><div class="slot-mode">${concert?'쉼':'아래에서 바꿀 수 있어요'}</div>`}</div>`;}
function editStrip(){const slot=state.project.slots[state.slot];if(!slot)return `<div class="edit-strip" style="display:block;text-align:center;padding:32px"><p class="quiet-help">왼쪽에서 놀이기구를 고르고 ${state.slot+1}번 칸을 눌러 소리를 담아요.</p><button class="btn secondary" data-action="add-slot" style="margin-top:13px">+ ${esc(nameOf(state.palette))} 담기</button></div>`;return `<div class="edit-strip"><div><div class="draw-head"><span>${state.slot+1}번 장면 · 소리의 모양을 그려요</span><div class="draw-tools"><button class="tone-slot-open" data-action="open-movement" data-target="slot">크게 그리기</button><button class="tone-slot-open" data-action="open-tone" data-target="slot" aria-label="이 장면 악기와 음정 바꾸기">♫ 악기·음정</button><button data-action="undo-draw">한 선 취소</button> <button data-action="clear-draw">지우기</button></div></div><div class="drawing-wrap ${isPitched(slot.tone)&&slot.tone.pitchMode==='follow'?'':'rhythm-drawing'}"><canvas id="drawing" width="600" height="194" aria-label="${isPitched(slot.tone)&&slot.tone.pitchMode==='follow'?'소리 그림 악보 그리기. 위는 높은 소리, 아래는 낮은 소리.':'소리 그림 악보 그리기. 선의 위치와 길이는 소리의 시작과 길이를 나타내요.'}"></canvas></div><p class="draw-hint">${!isPitched(slot.tone)?'그림의 위치와 길이에 따라 타악기 리듬을 연주해요.':slot.tone.pitchMode==='fixed'?'고른 한 음으로 연주해요. 그림선은 소리의 시작과 길이를 나타내요.':'손가락으로 그려요. 선과 점의 높낮이를 따라 음악이 돼요.'}</p></div><div class="edit-form"><div><label class="field-label" for="slot-word">이 장면의 소리말</label><input id="slot-word" class="word-input" data-field="slotWord" maxlength="48" value="${esc(slot.word)}" placeholder="내가 표현할 소리말"></div><div><div class="mode-line" role="group" aria-label="장면 연주 방법"><button class="btn secondary ${slot.mode==='music'?'chosen':''}" data-action="slot-mode" data-value="music" aria-pressed="${slot.mode==='music'}">${ICONS.music} 그림선 음악</button><button class="btn secondary ${slot.mode==='voice'?'chosen':''}" data-action="slot-mode" data-value="voice" ${!clips.has(slot.toyId)?'disabled':''} aria-pressed="${slot.mode==='voice'}">${ICONS.mic} 내 목소리</button></div><p class="draw-hint">${clips.has(slot.toyId)?'긴 목소리는 한 장면 길이만큼 재생돼요.':'목소리를 쓰려면 ‘소리 찾기’에서 먼저 녹음해요.'}</p></div></div></div>`;}
function compose(){return intro('소리 둘 · 쓱쓱, 그림으로 만드는 음악','나만의 그림 악보를 만들어요','놀이기구를 고르고 칸을 눌러요. 네 장면의 소리를 이어 작은 음악을 만들어요.','네 장면의 음악')+`<div class="compose-layout"><aside class="palette" aria-label="악보에 담을 소리"><h2>어떤 소리를 담을까요?</h2>${TOYS.map(t=>`<button class="palette-item ${state.palette===t.id?'chosen':''}" data-action="palette" data-toy="${t.id}" aria-pressed="${state.palette===t.id}">${toyArt(t.id)}<span>${esc(nameOf(t.id))}<small>${esc(soundOf(t.id).word)}</small></span></button>`).join('')}<p class="quiet-help">같은 소리를 여러 번 넣어도 좋아요.<br><br>빈 장면은 쉬는 부분이 돼요.</p></aside><section class="score-main" aria-label="그림 악보 편집"><div class="project-row"><label class="sr-only" for="project-title">작품 제목</label><input id="project-title" class="title-input" data-field="title" value="${esc(state.project.title)}" maxlength="40" placeholder="내 작품 이름"></div><div class="score-grid">${state.project.slots.map((s,i)=>slotHTML(s,i)).join('')}</div><div class="score-travel"><span>왼쪽부터 차례대로 연주해요</span><span>한 장면 = 4박 · 1 → 2 → 3 → 4</span></div>${editStrip()}</section></div>`+`<div class="footer-bar"><div class="transport"><button class="btn secondary" data-action="play-all">${state.playing?ICONS.stop:ICONS.play} ${state.playing?'연주 멈추기':'전체 들어보기'}</button><label class="tempo">빠르기 <input type="range" min="52" max="120" step="4" data-field="tempo" value="${state.project.tempo}" aria-label="전체 연주 빠르기"><span id="tempo-value">${state.project.tempo}</span></label></div><button class="btn primary next-btn" data-action="next">발표하러 가기 ${ICONS.arrow}</button></div><div class="footer-credit">목소리로도, 그림으로도 · 소리를 표현하는 여러 가지 방법</div>`;}
function perform(){const count=state.project.slots.filter(Boolean).length;return intro('소리 셋 · 두근두근, 나의 작은 음악회','소리 놀이터를 소개해요','내 악보를 보며 목소리와 몸짓으로 표현해요. 친구에게 나만의 음악을 소개해요.','나의 작은 음악회')+`<div class="perform-layout"><section class="concert-board" aria-label="내 작품 발표 악보">${count?'':'<div class="empty-warning">아직 담은 소리가 없어요. 악보 만들기에서 소리를 넣어 주세요.</div>'}<div class="concert-label">♪ 나만의 작은 소리 음악회 ♪</div><h2>${esc(state.project.title||'나의 소리 놀이터')}</h2><p class="concert-team" data-student-credit>${esc(state.project.studentName?'만든 사람 · '+state.project.studentName:'내가 만든 음악')}</p><div class="score-grid">${state.project.slots.map((s,i)=>slotHTML(s,i,true)).join('')}</div><div class="perform-controls"><button class="btn primary" data-action="play-all" ${!count?'disabled':''}>${state.playing?ICONS.stop:ICONS.play} ${state.playing?'연주 멈추기':'내 음악 연주'}</button><button class="btn secondary" data-action="present">${ICONS.expand} 크게 발표하기</button></div><div class="progress-track"><div class="progress-fill"></div></div><p class="concert-status" aria-live="polite">한 장면 ${sceneDuration(state.project.tempo).toFixed(1)}초 · 전체 약 ${Math.round(sceneDuration(state.project.tempo)*4)}초</p><button class="btn secondary exit-present" data-action="exit-present">크게 보기 끝내기</button></section><aside class="present-panel"><section class="panel"><h3>소리 탐험을 돌아보며</h3><label class="field-label" for="reflection">어떤 소리나 표현이 기억에 남나요?</label><textarea id="reflection" data-field="reflection" maxlength="200" placeholder="나는 ○○ 소리를 ○○하게 표현했어요.">${esc(state.project.reflection)}</textarea></section><section class="panel"><h3>내 작품 간직하기</h3><div class="download-buttons"><button class="btn secondary video-btn" data-action="download-video" ${!count?'disabled':''}>${ICONS.video} 그림+연주 동영상</button><button class="btn secondary" data-action="download-score" ${!count?'disabled':''}>${ICONS.download} 그림 악보 저장 (PNG)</button><button class="btn secondary" data-action="download-audio" ${!count?'disabled':''}>${ICONS.download} 연주 저장 (WAV)</button></div><p class="download-note">그림 악보와 연주를 한 영상에 담아요.<br>기기에 맞춰 MP4 또는 WebM으로 저장돼요.</p><div class="project-actions"><button data-action="export-project">작품 파일 저장</button><button data-action="import-project">열기</button></div></section><section class="panel script-card"><h3>이렇게 소개해도 좋아요</h3><p>“제 작품은 <b>${esc(state.project.title||'나의 소리 놀이터')}</b>입니다.<br>저는 <b>${esc(state.project.slots.find(Boolean)?nameOf(state.project.slots.find(Boolean).toyId):'○○')}</b>의 움직임을 소리로 표현했습니다.<br>어떤 장면이 떠오르는지 들어 보세요.”</p></section></aside></div>`+footer('<b>친구의 음악을 듣고 이야기해요.</b><br>어떤 움직임이 떠올랐나요? 어떤 표현이 재미있었나요?','다시 다듬기','back-compose');}
function render(){root.innerHTML=header()+`<main class="page">${state.view===0?explore():state.view===1?compose():perform()}</main>`;document.body.classList.toggle('presenting',state.presenting);if(state.view===1)setupDrawing();}
function navigate(view){if(state.recorder){toast('녹음을 끝낸 다음 이동해요.');return;}stopPlayback();state.view=Math.max(0,Math.min(2,view));state.presenting=false;render();window.scrollTo({top:0,behavior:'instant'});}
function stopPlayback(){stopAudio();clearTimeout(previewTimer);cancelAnimationFrame(raf);state.playing=false;document.querySelectorAll('.playing,.sound-playing').forEach(e=>e.classList.remove('playing','sound-playing'));const f=$('.progress-fill');if(f)f.style.width='0%';document.querySelectorAll('[data-action="play-all"]').forEach(b=>{b.innerHTML=ICONS.play+(state.view===1?' 전체 들어보기':' 내 음악 연주');});const status=$('.concert-status');if(status)status.textContent=`한 장면 ${sceneDuration(state.project.tempo).toFixed(1)}초 · 전체 약 ${Math.round(sceneDuration(state.project.tempo)*4)}초`;}
async function prepareBuffers(){await getAudio();for(const [id,blob]of clips)if(!buffers.has(id))try{buffers.set(id,await decodeBlob(blob));}catch{toast(`${nameOf(id)} 녹음을 읽지 못해 음악으로 연주해요.`);}}
async function playAll(){if(state.recorder)return;if(state.playing){stopPlayback();return;}if(!state.project.slots.some(Boolean)){toast('악보에 소리를 한 개 이상 담아 주세요.');return;}await prepareBuffers();const result=await playComposition(state.project,buffers);state.playing=true;document.querySelectorAll('[data-action="play-all"]').forEach(b=>{b.innerHTML=ICONS.stop+' 연주 멈추기';});let previous=-1;function tick(){const elapsed=result.context.currentTime-result.start;if(!state.playing)return;if(elapsed>=result.duration){stopPlayback();return;}const i=Math.max(0,Math.floor(elapsed/result.scene));if(i!==previous){document.querySelectorAll('.score-slot').forEach(e=>e.classList.toggle('playing',Number(e.dataset.slotIndex)===i));const status=$('.concert-status'),slot=state.project.slots[i];if(status)status.textContent=`${i+1}번째 장면 · ${slot?nameOf(slot.toyId)+' · '+(slot.word||soundOf(slot.toyId).word):'잠깐 쉬어요'}`;previous=i;}const f=$('.progress-fill');if(f)f.style.width=`${Math.max(0,elapsed/result.duration*100)}%`;raf=requestAnimationFrame(tick);}raf=requestAnimationFrame(tick);}
async function preview(id=state.toy,strokes,tone){if(state.recorder)return;stopPlayback();const t={...soundOf(id),tone:tone??soundOf(id).tone};const duration=await playToy(id,t,strokes??soundStrokes(soundOf(id)));const b=$(`[data-action="toy"][data-toy="${id}"]`);b?.classList.add('sound-playing');previewTimer=setTimeout(()=>b?.classList.remove('sound-playing'),duration*1000);}
async function startRecording(){
  if(state.recorder){state.recorder.stop();return;}
  if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('이 브라우저에서는 녹음할 수 없어요. HTTPS 주소의 Chrome에서 열거나 목소리로 직접 표현해요.');return;}
  stopPlayback();state.pendingMic=true;const button=$('[data-action="record"]');button.disabled=true;button.textContent='마이크 준비 중…';let stream;
  try{
    await getAudio();stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true},video:false});
    const mime=['audio/webm;codecs=opus','audio/mp4','audio/webm','audio/ogg;codecs=opus'].find(type=>MediaRecorder.isTypeSupported(type));
    const recorder=mime?new MediaRecorder(stream,{mimeType:mime}):new MediaRecorder(stream),chunks=[],id=state.toy;
    state.pendingMic=false;state.recorder=recorder;state.recordingToy=id;state.recStarted=Date.now();
    recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};
    recorder.onstop=async()=>{clearTimeout(recordTimer);clearInterval(recordTick);stream.getTracks().forEach(t=>t.stop());state.recorder=null;state.recordingToy=null;const blob=new Blob(chunks,{type:recorder.mimeType||mime||'audio/webm'});if(blob.size){clips.set(id,blob);buffers.delete(id);try{await putClip(id,blob);}catch{toast('녹음은 지금 사용할 수 있어요. 보관하려면 작품 파일을 저장해 주세요.');}toast('목소리를 담았어요! 내 목소리를 들어 보세요.');}else toast('녹음된 소리가 없어요. 다시 녹음해 주세요.');render();};
    recorder.onerror=()=>{try{recorder.stop();}catch{}toast('녹음이 중단됐어요. 마이크 연결을 확인해 주세요.');};
    recorder.start();render();recordTimer=setTimeout(()=>{if(recorder.state==='recording')recorder.stop();},6000);recordTick=setInterval(()=>{const label=$('#rec-label');if(label)label.textContent=`끝내기 · ${Math.min(6,(Date.now()-state.recStarted)/1000).toFixed(1)}초`;},100);
  }catch(error){stream?.getTracks().forEach(t=>t.stop());state.pendingMic=false;state.recorder=null;render();toast(error.name==='NotAllowedError'?'마이크 권한이 꺼져 있어요. 주소창의 사이트 설정에서 허용하거나 녹음 없이 활동해요.':error.name==='NotFoundError'?'마이크를 찾지 못했어요. 목소리로 직접 표현하거나 음악 기능을 이용해요.':'마이크를 열지 못했어요. 다른 녹음 앱을 닫고 다시 눌러 주세요.');}
}
function addSlot(i){if(state.playing)stopPlayback();const id=state.palette;state.project.slots[i]={toyId:id,word:soundOf(id).word,mode:'music',strokes:soundStrokes(soundOf(id)),tone:normalizeTone(soundOf(id).tone)};state.slot=i;state.paletteArmed=false;save();render();}
function refreshSlot(){const s=state.project.slots[state.slot],el=$(`[data-slot-index="${state.slot}"]`);if(s&&el){el.querySelector('.slot-graph').innerHTML=graphSVG(s.strokes,TOYS.find(t=>t.id===s.toyId).color);el.querySelector('.slot-word').textContent=s.word;}}
function setupDrawing(){const canvas=$('#drawing'),slot=state.project.slots[state.slot];if(!canvas||!slot)return;bindDrawing(canvas,slot,{color:TOYS.find(t=>t.id===slot.toyId).color,onStart:stopPlayback,onChange:()=>{save();refreshSlot();},onLimit:()=>toast('선은 12개까지 그려요. 한 선 취소나 지우기를 눌러요.')});}
function openMovement(target){
  stopPlayback();const source=target==='slot'?state.project.slots[state.slot]:soundOf(state.toy);if(!source)return;
  const toyId=target==='slot'?source.toyId:state.toy,tone=normalizeTone(source.tone);if(isPitched(tone))tone.pitchMode='follow';
  state.movementEditor={target,id:target==='slot'?state.slot:state.toy,toyId,tone,strokes:target==='slot'?structuredClone(source.strokes):Array.isArray(source.strokes)?soundStrokes(source):[]};
  $('#movement-title').textContent=(target==='slot'?`${state.slot+1}번 장면`:nameOf(toyId))+' · 소리의 움직임 그리기';
  $('#movement-tone').textContent=toneLabel(tone);
  $('#movement-save-note').textContent=target==='slot'?'‘이 그림으로 담기’를 누르면 이 장면에 저장돼요.':'‘이 그림으로 담기’를 누르면 저장돼요. 새로 악보에 담을 때도 이 움직임이 들어가요.';
  $('#movement-help').textContent=isPitched(tone)?'왼쪽에서 오른쪽으로 그려요. 위는 높은 소리, 아래는 낮은 소리예요. 점을 콕 찍어도 좋아요.':'왼쪽에서 오른쪽으로 그려요. 선과 점의 위치와 길이에 따라 타악기 리듬이 돼요.';
  $('#movement-axis').classList.toggle('rhythm-drawing',!isPitched(tone));
  $('#movement-presets').innerHTML=SHAPES.map(x=>`<button class="movement-preset" data-action="movement-preset" data-value="${x.id}"><b>${x.glyph}</b>${x.label}</button>`).join('');
  $('#movement-dialog').showModal();
  movementDrawing=bindDrawing($('#movement-canvas'),state.movementEditor,{color:TOYS.find(t=>t.id===toyId).color,onStart:stopPlayback,onChange:updateMovementState,onLimit:()=>toast('선은 12개까지 그려요. 한 선 취소나 모두 지우기를 눌러요.')});updateMovementState();
}
function updateMovementState(){const editor=state.movementEditor;if(!editor)return;$('#movement-empty').hidden=editor.strokes.length>0;$('#movement-count').textContent=`${editor.strokes.length} / 12개 선`;$('[data-action="movement-undo"]').disabled=editor.strokes.length===0;}
function closeMovement(){stopPlayback();movementDrawing?.finish();movementDrawing?.destroy();movementDrawing=null;state.movementEditor=null;$('#movement-dialog').close();}
function applyMovement(){const editor=state.movementEditor;if(!editor)return;movementDrawing?.finish();const source=editor.target==='slot'?state.project.slots[editor.id]:soundOf(editor.id);if(source){source.strokes=structuredClone(editor.strokes);source.tone=normalizeTone(editor.tone);if(editor.target==='slot')source.mode='music';}closeMovement();save();render();toast('그린 움직임을 담았어요. 그림선을 따라 소리를 들어 보세요.');}
async function previewMovement(){const editor=state.movementEditor;if(!editor)return;movementDrawing?.finish();stopPlayback();await playToy(editor.toyId,{...soundOf(editor.toyId),tone:editor.tone},editor.strokes);}

function download(blob,filename){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function filename(){return [state.project.studentName.trim(),state.project.title.trim()||'나의_소리_놀이터'].filter(Boolean).join('_').replace(/[\\/:*?"<>|\u0000-\u001f]/g,'_').slice(0,80);}
async function exportProject(){const voice={};for(const [id,blob]of clips)voice[id]=await clipToDataURL(blob);download(new Blob([JSON.stringify({app:'sorirang-playground',project:state.project,recordings:voice},null,2)],{type:'application/json'}),filename()+'.json');toast('악보와 녹음이 담긴 작품 파일을 저장했어요.');}
async function importProject(file){
  if(file.size>12000000)throw new Error('작품 파일이 너무 커요. 12MB 이하의 파일을 선택해 주세요.');
  const raw=JSON.parse(await file.text());if(raw.app!=='sorirang-playground')throw new Error('소리랑 놀이터에서 저장한 작품 파일을 선택해 주세요.');
  const p=validateProject(raw.project),nextClips=new Map();for(const t of TOYS)if(raw.recordings?.[t.id])nextClips.set(t.id,dataURLToClip(raw.recordings[t.id]));
  if(!confirm('지금 화면의 작품 대신 이 파일을 열까요? 필요한 작품은 먼저 파일로 저장해 주세요.'))return;
  stopPlayback();state.project=p;clips=nextClips;buffers.clear();try{await replaceClips(nextClips);}catch{toast('녹음을 기기에 보관하지 못했어요. 작품 파일을 따로 보관해 주세요.');}save();navigate(1);toast('작품을 열었어요. 녹음한 목소리도 함께 불러왔어요.');
}
function roundRect(ctx,x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(fill){ctx.fillStyle=fill;ctx.fill();}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=2;ctx.stroke();}}
function wrap(ctx,text,x,y,width,lineHeight,maxLines=4){let line='',count=0;for(const char of [...text]){if(ctx.measureText(line+char).width>width&&line){ctx.fillText(line,x,y+count*lineHeight);line='';count++;if(count>=maxLines)return;}line+=char;}if(line)ctx.fillText(line,x,y+count*lineHeight);}
let sceneImagePromise;
function loadSceneImage(){return sceneImagePromise??=new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>{sceneImagePromise=null;reject(new Error('놀이터 그림을 읽지 못했어요. 연결을 확인하고 다시 눌러 주세요.'));};image.src=SCENE.src;});}
async function downloadScore(){
  const p=structuredClone(state.project),sceneImage=await loadSceneImage(),canvas=document.createElement('canvas');canvas.width=1800;canvas.height=p.reflection.trim()?1250:1010;const c=canvas.getContext('2d');c.fillStyle='#fff7ee';c.fillRect(0,0,canvas.width,canvas.height);c.textAlign='center';c.fillStyle='#738b6c';c.font='700 18px sans-serif';c.fillText('소리랑 놀이터  ·  ♪ 나만의 작은 소리 음악회 ♪',900,78);c.fillStyle='#29463e';c.font='800 46px sans-serif';wrap(c,p.title||'나의 소리 놀이터',900,155,1570,59,2);c.font='24px sans-serif';c.fillStyle='#78916d';c.fillText(p.studentName?'만든 사람 · '+p.studentName:'내가 만든 음악',900,265);
  for(let i=0;i<4;i++){const slot=p.slots[i],x=70+i*420,w=400;roundRect(c,x,310,w,520,25,'#fffdfa','#d8c2e8');c.textAlign='left';c.fillStyle='#81927b';c.font='700 18px sans-serif';c.fillText('SCENE '+String(i+1).padStart(2,'0'),x+23,349);c.textAlign='center';if(!slot){c.fillStyle='#9ba78f';c.font='28px sans-serif';c.fillText('잠깐 쉬어요',x+200,550);continue;}const t=TOYS.find(t=>t.id===slot.toyId),[sx,sy,sw,sh]=t.crop.map((v,j)=>v*(j%2?SCENE.height:SCENE.width)),scale=Math.min(260/sw,172/sh),dw=sw*scale,dh=sh*scale;c.drawImage(sceneImage,sx,sy,sw,sh,x+(400-dw)/2,365+(172-dh)/2,dw,dh);c.fillStyle='#476448';c.font='700 25px sans-serif';wrap(c,nameOf(t.id),x+200,563,350,32,2);c.fillStyle=t.color;c.font='800 30px sans-serif';wrap(c,slot.word||soundOf(t.id).word,x+200,631,340,37,2);for(let j=0;j<4;j++){c.strokeStyle='#edf0e3';c.lineWidth=1;c.beginPath();c.moveTo(x+25,705+j*23);c.lineTo(x+375,705+j*23);c.stroke();}c.strokeStyle=t.color;c.fillStyle=t.color;c.lineWidth=5;c.lineCap='round';c.lineJoin='round';for(const line of slot.strokes){if(!line.length)continue;c.beginPath();c.moveTo(x+27+line[0].x*346,700+line[0].y*90);if(line.length===1){c.arc(x+27+line[0].x*346,700+line[0].y*90,3,0,Math.PI*2);c.fill();}else{for(const q of line.slice(1))c.lineTo(x+27+q.x*346,700+q.y*90);c.stroke();}}c.fillStyle='#7d8e73';c.font='18px sans-serif';c.fillText(slot.mode==='voice'&&clips.has(t.id)?'내가 녹음한 목소리':musicSummary(slot),x+200,812);}
  c.textAlign='center';c.fillStyle='#8b987e';c.font='20px sans-serif';c.fillText('왼쪽부터 차례대로  ·  한 장면 4박  ·  빠르기 ♩ = '+p.tempo,900,888);
  if(p.reflection.trim()){roundRect(c,70,935,1660,210,20,'#edf0e1');c.textAlign='left';c.fillStyle='#4d7355';c.font='700 22px sans-serif';c.fillText('소리 탐험을 돌아보며',100,977);c.fillStyle='#61745b';c.font='23px sans-serif';wrap(c,p.reflection,100,1017,1590,33,4);}
  c.textAlign='center';c.fillStyle='#98a28e';c.font='17px sans-serif';c.fillText('소리와 움직임을 목소리와 음악으로 표현해요',900,canvas.height-40);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw new Error('그림 파일을 만들지 못했어요. 다시 눌러 주세요.');download(blob,filename()+'.png');toast('내 그림 악보를 저장했어요.');
}
function closeVideo(){
  videoAbort?.abort();
  const player=$('#video-playback');player.pause();player.removeAttribute('src');player.load();
  if(videoURL){URL.revokeObjectURL(videoURL);videoURL=null;}
  $('#video-download').removeAttribute('href');$('#video-dialog').close();
}
async function downloadVideo(){
  if(!videoSupported())throw new Error('이 브라우저에서는 동영상을 만들 수 없어요. Chrome 또는 Samsung Internet에서 열어 주세요. 그림과 연주는 따로 저장할 수 있어요.');
  if(!state.project.slots.some(Boolean))throw new Error('악보에 소리를 한 개 이상 담아 주세요.');
  stopPlayback();state.busy=true;const controller=new AbortController();videoAbort=controller;
  const dialog=$('#video-dialog'),player=$('#video-playback'),canvas=$('#video-canvas'),link=$('#video-download'),progress=$('#video-progress'),status=$('#video-status'),hint=$('#video-hint');
  if(videoURL){URL.revokeObjectURL(videoURL);videoURL=null;}player.pause();player.removeAttribute('src');player.load();player.hidden=true;canvas.hidden=false;link.hidden=true;progress.hidden=false;progress.value=0;status.textContent='그림과 연주를 준비하고 있어요.';hint.textContent='연주가 끝날 때까지 이 화면을 열어 두세요. 다른 화면으로 이동하면 만들기가 취소돼요.';
  const cancel=dialog.querySelector('.video-actions button');cancel.textContent='만들기 취소';dialog.showModal();
  try{
    await prepareBuffers();
    const p=structuredClone(state.project),voices=new Map(buffers),baseName=filename();
    const result=await recordCompositionVideo(p,voices,canvas,{signal:controller.signal,onProgress:value=>{progress.value=value;status.textContent=`그림과 연주를 담는 중… ${Math.round(value)}%`;}});
    if(controller.signal.aborted)return;
    videoURL=URL.createObjectURL(result.blob);player.src=videoURL;player.hidden=false;canvas.hidden=true;link.href=videoURL;link.download=baseName+'.'+result.extension;link.textContent=`동영상 내려받기 (${result.extension.toUpperCase()})`;link.hidden=false;progress.hidden=true;status.textContent='완성했어요! 영상을 확인하고 아래 버튼으로 저장해요.';hint.textContent='저장한 동영상에는 그림 악보와 선택한 연주 소리가 함께 들어 있어요.';cancel.textContent='닫기';
  }catch(error){if(error.name!=='AbortError'){canvas.hidden=true;progress.hidden=true;status.textContent=error.message||'동영상을 만들지 못했어요. 다시 시도해 주세요.';hint.textContent='다른 브라우저에서 다시 시도하거나 그림 악보와 연주를 따로 저장할 수 있어요.';cancel.textContent='닫기';}else if(dialog.open){dialog.close();toast('동영상 만들기를 취소했어요. 작품은 그대로 있어요.');}}
  finally{if(videoAbort===controller)videoAbort=null;state.busy=false;}
}
async function action(button){
  const {action:a}=button.dataset;
  if(state.pendingMic){toast('브라우저의 마이크 권한 안내를 먼저 확인해요.');return;}
  if(videoAbort&&a!=='close-video'){toast('동영상 만들기가 끝날 때까지 잠깐 기다려 주세요.');return;}
  if(state.busy&&['download-audio','download-score','download-video','export-project','import-project','record','reset'].includes(a)){toast('파일을 준비하고 있어요. 잠깐만 기다려 주세요.');return;}
  if(state.recorder&&!['record'].includes(a)){toast('녹음을 끝낸 다음 선택해요.');return;}
  switch(a){
    case 'view':navigate(Number(button.dataset.view));break;
    case 'next':navigate(state.view+1);break;
    case 'back-compose':navigate(1);break;
    case 'help':$('#help-dialog').showModal();break;
    case 'close-help':$('#help-dialog').close();break;
    case 'show-scene':$('#scene-dialog-body').innerHTML=sceneView(true);$('#scene-dialog').showModal();break;
    case 'close-scene':$('#scene-dialog').close();break;
    case 'toy':if($('#scene-dialog').open)$('#scene-dialog').close();stopPlayback();state.toy=button.dataset.toy;state.visited.add(state.toy);render();break;
    case 'shape':stopPlayback();soundOf(state.toy).shape=button.dataset.value;delete soundOf(state.toy).strokes;save();render();break;
    case 'open-movement':openMovement(button.dataset.target);break;
    case 'close-movement':closeMovement();break;
    case 'apply-movement':applyMovement();break;
    case 'preview-movement':await previewMovement();break;
    case 'movement-undo':case 'movement-clear':if(state.movementEditor){stopPlayback();movementDrawing?.finish();if(a==='movement-undo')state.movementEditor.strokes.pop();else state.movementEditor.strokes=[];movementDrawing?.paint();updateMovementState();}break;
    case 'movement-preset':if(state.movementEditor){stopPlayback();movementDrawing?.finish();state.movementEditor.strokes=defaultStrokes(button.dataset.value);movementDrawing?.paint();updateMovementState();}break;
    case 'setting':soundOf(state.toy)[button.dataset.key]=button.dataset.value;save();render();break;
    case 'open-tone':openTone(button.dataset.target);break;
    case 'cancel-tone':closeTone();break;
    case 'apply-tone':applyTone();break;
    case 'preview-tone':await previewTone();break;
    case 'tone-instrument':if(state.toneEditor){stopPlayback();state.toneEditor.tone.instrument=button.dataset.value;renderToneEditor('[data-action="tone-instrument"][data-value="'+button.dataset.value+'"]');}break;
    case 'tone-note':if(state.toneEditor){state.toneEditor.tone.note=button.dataset.value;renderToneEditor('[data-action="tone-note"][data-value="'+button.dataset.value+'"]');await playTone(state.toneEditor.tone);}break;
    case 'tone-setting':if(state.toneEditor){stopPlayback();state.toneEditor.tone[button.dataset.key]=button.dataset.key==='octave'?Number(button.dataset.value):button.dataset.value;renderToneEditor('[data-action="tone-setting"][data-key="'+button.dataset.key+'"][data-value="'+button.dataset.value+'"]');}break;
    case 'preview':await preview();break;
    case 'record':await startRecording();break;
    case 'listen-voice':await prepareBuffers();if(buffers.has(state.toy)){stopPlayback();await playRecording(buffers.get(state.toy));}break;
    case 'download-voice':{const blob=clips.get(state.toy);if(blob)download(blob,filename()+'_'+nameOf(state.toy)+'_목소리.'+(blob.type.includes('mp4')?'m4a':blob.type.includes('ogg')?'ogg':'webm'));break;}
    case 'remove-voice':if(confirm('이 놀이기구의 녹음을 지울까요?')){stopPlayback();clips.delete(state.toy);buffers.delete(state.toy);try{await putClip(state.toy,null);}catch{}state.project.slots.forEach(s=>{if(s?.toyId===state.toy)s.mode='music';});save();render();toast('녹음을 지웠어요. 다시 녹음할 수 있어요.');}break;
    case 'palette':stopPlayback();state.palette=button.dataset.toy;state.paletteArmed=true;render();toast(nameOf(state.palette)+' 소리를 담을 칸을 눌러요.');break;
    case 'select-slot':{const i=Number(button.dataset.index);if(!state.project.slots[i]||(state.paletteArmed&&state.project.slots[i].toyId!==state.palette))addSlot(i);else{stopPlayback();state.slot=i;state.palette=state.project.slots[i].toyId;state.paletteArmed=false;render();}break;}
    case 'add-slot':addSlot(state.slot);break;
    case 'remove-slot':stopPlayback();state.project.slots[Number(button.dataset.index)]=null;save();render();break;
    case 'slot-mode':{const s=state.project.slots[state.slot];if(s){stopPlayback();s.mode=button.dataset.value;save();render();}break;}
    case 'undo-draw':{const s=state.project.slots[state.slot];if(s){stopPlayback();s.strokes.pop();save();render();}break;}
    case 'clear-draw':{const s=state.project.slots[state.slot];if(s){stopPlayback();s.strokes=[];save();render();}break;}
    case 'play-all':await playAll();break;
    case 'play-slot':{const s=state.project.slots[Number(button.dataset.index)];if(!s){toast('소리 없이 잠깐 쉬는 장면이에요.');break;}if(s.mode==='voice'&&clips.has(s.toyId)){await prepareBuffers();stopPlayback();if(buffers.has(s.toyId))await playRecording(buffers.get(s.toyId));else await preview(s.toyId,s.strokes,s.tone);}else await preview(s.toyId,s.strokes,s.tone);break;}
    case 'empty-slot':toast('소리 없이 잠깐 쉬는 장면이에요.');break;
    case 'present':state.presenting=true;document.body.classList.add('presenting');window.scrollTo({top:0,behavior:'instant'});if(document.documentElement.requestFullscreen)try{await document.documentElement.requestFullscreen();}catch{}break;
    case 'exit-present':await exitPresent();break;
    case 'download-video':await downloadVideo();break;
    case 'close-video':closeVideo();break;
    case 'download-score':state.busy=true;button.disabled=true;try{await downloadScore();}finally{state.busy=false;button.disabled=false;}break;
    case 'download-audio':{state.busy=true;button.disabled=true;const label=button.innerHTML;button.textContent='연주 파일 만드는 중…';try{await prepareBuffers();const blob=await renderComposition(state.project,buffers);download(blob,filename()+'.wav');toast('내 연주를 WAV 파일로 저장했어요.');}finally{state.busy=false;button.disabled=false;button.innerHTML=label;}break;}
    case 'export-project':state.busy=true;try{await exportProject();}finally{state.busy=false;}break;
    case 'import-project':$('#import-file').value='';$('#import-file').click();break;
    case 'reset':if(confirm('지금 작품과 녹음을 지우고 새로 시작할까요? 보관하려면 먼저 작품 파일을 저장해 주세요.')){stopPlayback();state.project=freshProject();clips.clear();buffers.clear();try{await replaceClips(clips);}catch{}state.toy='slide';state.palette='slide';state.slot=0;state.visited=new Set(['slide']);save();$('#help-dialog').close();navigate(0);toast('새로운 소리 탐험을 시작해요.');}break;
  }
}
async function exitPresent(){state.presenting=false;document.body.classList.remove('presenting');if(document.fullscreenElement)try{await document.exitFullscreen();}catch{}}
document.addEventListener('click',e=>{const button=e.target.closest('button[data-action]');if(!button||button.disabled)return;action(button).catch(error=>{console.error(error);toast(error.message||'실행하지 못했어요. 다시 눌러 주세요.');});});
document.addEventListener('input',e=>{const el=e.target,key=el.dataset.field;if(!key)return;
  if(key==='soundWord')soundOf(state.toy).word=el.value;
  else if(key==='slotWord'){const s=state.project.slots[state.slot];if(s){s.word=el.value;refreshSlot();}}
  else if(key==='tempo'){if(state.playing)stopPlayback();state.project.tempo=Number(el.value);$('#tempo-value').textContent=el.value;}
  else if(['title','studentName','reflection'].includes(key)){state.project[key]=el.value;if(key==='studentName')document.querySelectorAll('[data-student-credit]').forEach(n=>n.textContent=el.value?'만든 사람 · '+el.value:'내가 만든 음악');}
  save();
});
$('#movement-dialog').addEventListener('cancel',e=>{e.preventDefault();closeMovement();});
$('#video-dialog').addEventListener('cancel',e=>{e.preventDefault();closeVideo();});
$('#tone-dialog').addEventListener('cancel',()=>{stopPlayback();state.toneEditor=null;});
$('#import-file').addEventListener('change',e=>{const file=e.target.files[0];if(file)importProject(file).catch(error=>{console.error(error);toast(error.message||'작품 파일을 열지 못했어요.');});});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.presenting)exitPresent();});
document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement&&state.presenting){state.presenting=false;document.body.classList.remove('presenting');}});
document.addEventListener('visibilitychange',()=>{if(document.hidden){videoAbort?.abort();stopPlayback();if(state.recorder?.state==='recording')state.recorder.stop();}});
window.addEventListener('pagehide',()=>{try{localStorage.setItem(KEY,JSON.stringify(state.project));}catch{}if(state.recorder?.state==='recording')state.recorder.stop();});
render();
loadClips().then(result=>{clips=result;if(!state.recorder&&!state.movementEditor)render();}).catch(()=>{storageOK=false;const label=$('.save-status');if(label)label.textContent='작품 파일로 저장해요';});
